<?php get_header(); ?><main id="primary" class="site-main content-area"><header class="page-header"><h1 class="entry-title"><?php esc_html_e( 'Latest posts', 'geekforge' ); ?></h1></header><?php if ( have_posts() ) : ?><div class="gf-grid"><?php while ( have_posts() ) : the_post(); ?><article <?php post_class( 'gf-card' ); ?>><h2 class="entry-title"><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><div class="entry-meta"><?php echo esc_html( get_the_date() ); ?></div><?php the_excerpt(); ?></article><?php endwhile; ?></div><?php the_posts_pagination(); else : ?><p><?php esc_html_e( 'Nothing found.', 'geekforge' ); ?></p><?php endif; ?></main><?php get_footer(); ?>
